<?php
require_once __DIR__ . '/includes_excel_data.php'; ensureExcelTables($pdo);
$defaultFY = latest_excel_fiscal_year($pdo); $fy=(int)($_GET['fy']??$defaultFY); if($fy<2500||$fy>2700)$fy=$defaultFY; $valid=['ap','online','booth']; $selected=[]; foreach($valid as $s){if(isset($_GET[$s]))$selected[]=$s;} if(!$selected)$selected=$valid;
$where=['source_section IN ('.implode(',',array_fill(0,count($selected),'?')).')'];$params=$selected; if($fy>=2500&&$fy<=2700){$where[]='fiscal_year=?';$params[]=$fy;}
$sql='SELECT source_section, COUNT(*) c, COALESCE(SUM(CAST(NULLIF(REPLACE(`ยอดสุทธิ`,",","") ,"") AS DECIMAL(14,2))),0) revenue, SUM(`ประเภทการสมัคร`="สมัครใหม่") new_count, SUM(`ประเภทการสมัคร`="ต่ออายุ") renew_count FROM excel_member_records WHERE '.implode(' AND ',$where).' GROUP BY source_section';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$sumCount=0;$sumRev=0;$sumNew=0;$sumRenew=0;foreach($rows as $r){$sumCount+=(int)$r['c'];$sumRev+=(float)$r['revenue'];$sumNew+=(int)$r['new_count'];$sumRenew+=(int)$r['renew_count'];}
$labels=['ap'=>'สมัครที่ อพ.','online'=>'สมัครออนไลน์','booth'=>'ออกบูธ'];$icons=['ap'=>'🏛️','online'=>'🌐','booth'=>'📢'];
$chartRows=[]; foreach($valid as $sec){ foreach($rows as $r){ if($r['source_section']===$sec){ $chartRows[]=$r; break; } } }
$chartLabels=array_map(fn($r)=>$labels[$r['source_section']]??$r['source_section'],$chartRows);
$chartCounts=array_map(fn($r)=>(int)$r['c'],$chartRows); $chartRevenue=array_map(fn($r)=>(float)$r['revenue'],$chartRows);
?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>เปรียบเทียบ 3 ส่วน</title><link rel="stylesheet" href="assets/css/style.css?v=10"></head><body><?php $activePage = basename($_SERVER['SCRIPT_NAME'] ?? 'data_sources.php'); require __DIR__ . '/includes/navigation.php'; ?><main class="main"><div class="topbar"><div><h1>เปรียบเทียบข้อมูล 3 ส่วน</h1><p>เลือกดูข้อมูลจาก Excel ชุดเดียวกัน โดยไม่ต้องกรอกซ้ำ</p></div></div><div class="content"><div class="card"><form method="get"><div style="display:flex;flex-wrap:wrap;gap:18px;align-items:center"><label><input type="checkbox" name="ap" value="1" <?=in_array('ap',$selected,true)?'checked':''?>> 🏛️ สมัครที่ อพ.</label><label><input type="checkbox" name="online" value="1" <?=in_array('online',$selected,true)?'checked':''?>> 🌐 สมัครออนไลน์</label><label><input type="checkbox" name="booth" value="1" <?=in_array('booth',$selected,true)?'checked':''?>> 📢 ออกบูธ</label><label>ปีงบประมาณ <input class="form-control" style="display:inline-block;width:120px" type="number" name="fy" value="<?=e($fy)?>"></label><button class="btn btn-primary" type="submit">แสดงผล</button></div></form></div><div class="stats"><div class="stat-card"><div><div class="stat-label">รายการที่เลือก</div><div class="stat-number"><?=number_format($sumCount)?></div></div><div class="stat-icon blue">📄</div></div><div class="stat-card"><div><div class="stat-label">สมัครใหม่</div><div class="stat-number"><?=number_format($sumNew)?></div></div><div class="stat-icon green">🆕</div></div><div class="stat-card"><div><div class="stat-label">ต่ออายุ</div><div class="stat-number"><?=number_format($sumRenew)?></div></div><div class="stat-icon orange">🔄</div></div><div class="stat-card"><div><div class="stat-label">ยอดสุทธิ</div><div class="stat-number">฿<?=number_format($sumRev,2)?></div></div><div class="stat-icon purple">💰</div></div></div><div class="grid" style="margin-bottom:20px"><div class="card"><div class="card-header"><div><div class="card-title">📊 เปรียบเทียบจำนวนรายการ</div><div class="card-subtitle">เฉพาะส่วนที่เลือก · ปีงบประมาณ <?=e($fy)?></div></div></div><div class="chart-container"><canvas id="sectionCountChart"></canvas></div></div><div class="card"><div class="card-header"><div><div class="card-title">💰 เปรียบเทียบยอดสุทธิ</div><div class="card-subtitle">เฉพาะส่วนที่เลือก · ปีงบประมาณ <?=e($fy)?></div></div></div><div class="chart-container"><canvas id="sectionRevenueChart"></canvas></div></div></div><div class="card"><div class="card-title">สรุปตามส่วนที่เลือก</div><div style="overflow:auto"><table class="building-table"><thead><tr><th>ส่วน</th><th class="right">รายการ</th><th class="right">สมัครใหม่</th><th class="right">ต่ออายุ</th><th class="right">ยอดสุทธิ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($icons[$r['source_section']]??'')?> <?=e($labels[$r['source_section']]??$r['source_section'])?></td><td class="right"><?=number_format((int)$r['c'])?></td><td class="right"><?=number_format((int)$r['new_count'])?></td><td class="right"><?=number_format((int)$r['renew_count'])?></td><td class="right">฿<?=number_format((float)$r['revenue'],2)?></td></tr><?php endforeach;?></tbody></table></div></div></div></main><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>
const sectionLabels=<?=json_encode($chartLabels,JSON_UNESCAPED_UNICODE)?>, sectionCounts=<?=json_encode($chartCounts)?>, sectionRevenue=<?=json_encode($chartRevenue)?>;
const countCanvas=document.getElementById('sectionCountChart'); if(countCanvas&&typeof Chart!=='undefined') new Chart(countCanvas,{type:'bar',data:{labels:sectionLabels,datasets:[{label:'รายการ',data:sectionCounts,borderWidth:1}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});
const revenueCanvas=document.getElementById('sectionRevenueChart'); if(revenueCanvas&&typeof Chart!=='undefined') new Chart(revenueCanvas,{type:'bar',data:{labels:sectionLabels,datasets:[{label:'ยอดสุทธิ',data:sectionRevenue,borderWidth:1}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:c=>'฿'+Number(c.raw||0).toLocaleString('th-TH')}}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'฿'+Number(v).toLocaleString('th-TH')}}}}});
</script></body></html>
